package com.yuexin.bmp.agent.task.profit.source;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import java.security.MessageDigest;
@Service
public class ProfitSourceService {
 private final JdbcTemplate db;private final ObjectMapper json;private final SourceProperties p;private final ProfitSourceGateway gateway;
 public ProfitSourceService(JdbcTemplate db,ObjectMapper j,SourceProperties p,ProfitSourceGateway g){this.db=db;json=j;this.p=p;gateway=g;}
 private String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
 @SuppressWarnings("unchecked")private Map<String,Object>decode(String s){try{return json.readValue(s,Map.class);}catch(Exception e){throw new IllegalStateException(e);}}
 private static void require(boolean yes,String code){if(!yes)throw new SourceException(code,"SOURCE_CHANGED".equals(code)?409:"INVALID_ARGUMENT".equals(code)?400:422,false);}
 private LocalDate day(Object x){try{LocalDate d=LocalDate.parse(String.valueOf(x));if(!d.isBefore(LocalDate.now(ZoneId.of("Asia/Shanghai"))))throw new Exception();return d;}catch(Exception e){throw new SourceException("INVALID_ARGUMENT",400,false);}}
 public static String hash(String s){try{byte[]b=MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));StringBuilder o=new StringBuilder();for(byte x:b)o.append(String.format("%02x",x));return o.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 @SuppressWarnings("unchecked")public Map<String,Object> domestic(Map<String,Object> request){
  LocalDate start=day(request.get("startDate")),end=day(request.get("endDate"));require(!start.isAfter(end),"INVALID_ARGUMENT");
  require(new HashSet<>(Arrays.asList("Customer","QuasiCustomer","Agent","CHANNEL")).equals(new HashSet<>((List<String>)request.getOrDefault("customerTypes",Collections.emptyList()))),"MAPPING_UNCONFIRMED");
  require("INCLUDED".equals(request.get("taxBasis"))&&"OPERATING".equals(request.get("indicatorView")),"MAPPING_UNCONFIRMED");
  Map<String,Object>page=ConfiguredSourceGateway.map(request.get("page"));int n=((Number)page.getOrDefault("number",1)).intValue(),size=((Number)page.getOrDefault("size",200)).intValue();require(n>0&&size>0&&size<=1000,"INVALID_ARGUMENT");
  Map<String,Object>criteria=new TreeMap<>(request);criteria.remove("queryId");criteria.remove("page");String binding=hash(encode(criteria));String id=(String)request.get("queryId");Map<String,Object>frozen;
  if(id!=null){List<Map<String,Object>>r=db.queryForList("SELECT * FROM profit_source_receipt WHERE receipt_id=? AND binding_hash=? AND expires_at>CURRENT_TIMESTAMP",id,binding);if(r.isEmpty())throw new SourceException("SOURCE_CHANGED",409,false);frozen=decode((String)r.get(0).get("payload"));}
  else{
   require(n==1,"INVALID_ARGUMENT");require(p.isMappingConfirmed()&&p.isStableReadConfirmed()&&!p.getCustomerIds().isEmpty(),"MAPPING_UNCONFIRMED");
   List<Map<String,Object>>rows=new ArrayList<>();Set<String>ids=new HashSet<>();long total=-1;
   for(int ix=1;ix<=10000;ix++){
    Map<String,Object>q=new HashMap<>();q.put("cycle","Day");q.put("source","Detail");q.put("marketIndex",false);q.put("customerIds",p.getCustomerIds());q.put("startTime",start.atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant().toEpochMilli());q.put("endTime",end.plusDays(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant().toEpochMilli());
    Map<String,Object>pg=new HashMap<>();pg.put("pageNumber",ix);pg.put("pageSize",200);pg.put("sorts",Collections.singletonList(new HashMap<String,Object>(){{put("fieldName","id");put("order","Asc");}}));q.put("page",pg);
    Map<String,Object>raw=gateway.domesticPage(q);Object source=raw.get("data");Object count=raw.get("totalCount");require(source instanceof List&&count instanceof Number,"SOURCE_INCOMPLETE");long countValue=((Number)count).longValue();if(total<0)total=countValue;require(total>=0&&total==countValue,"SOURCE_CHANGED");
    List<?>batch=(List<?>)source;for(Object v:batch){Map<String,Object>r=ConfiguredSourceGateway.map(v);String rid=String.valueOf(r.get("id"));require(!"null".equals(rid)&&ids.add(rid),"SOURCE_INCOMPLETE");String code=String.valueOf(r.getOrDefault("entCode",""));String name=p.getEnterpriseNames().get(code);require(name!=null&&!name.trim().isEmpty()&&!code.isEmpty(),"MAPPING_UNCONFIRMED");Object tm=r.get("time");require(tm instanceof Number,"MAPPING_UNCONFIRMED");String date=Instant.ofEpochMilli(((Number)tm).longValue()).atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString();require(date.compareTo(start.toString())>=0&&date.compareTo(end.toString())<=0,"SOURCE_INCOMPLETE");
     Map<String,Object>out=new LinkedHashMap<>();out.put("timeStr",date);out.put("entCode",code);out.put("entName",name);out.put("smsIncome",amount(r.get("smsIncome")));out.put("smsProfit",amount(r.get("smsOperateProfit")));rows.add(out);
    }require(rows.size()<=total,"SOURCE_INCOMPLETE");if(rows.size()==total)break;require(!batch.isEmpty()&&ix<10000,"SOURCE_INCOMPLETE");
   }frozen=new HashMap<>();frozen.put("rows",rows);frozen.put("fetchedAt",OffsetDateTime.now(ZoneId.of("Asia/Shanghai")).toString());id="dq-"+UUID.randomUUID();db.update("INSERT INTO profit_source_receipt(receipt_id,binding_hash,payload,expires_at) VALUES(?,?,?,?)",id,binding,encode(frozen),java.sql.Timestamp.from(Instant.now().plusSeconds(604800)));
  }
  List<?>rows=(List<?>)frozen.get("rows");long offset=(long)(n-1)*size;require(offset<=rows.size(),"INVALID_ARGUMENT");Map<String,Object>out=new LinkedHashMap<>();out.put("queryId",id);out.put("success",true);out.put("code","GB:0000");out.put("data",rows.subList((int)offset,Math.min(rows.size(),(int)Math.min(Integer.MAX_VALUE,offset+size))));out.put("totalCount",rows.size());out.put("pageNumber",n);out.put("pageSize",size);Map<String,Object>meta=new HashMap<>();meta.put("source","BMP_BI");meta.put("fetchedAt",frozen.get("fetchedAt"));meta.put("sourceVersion",null);meta.put("adapterVersion","v1");meta.put("consistency","FROZEN_RECEIPT");meta.put("receiptSha256",hash(encode(frozen)));out.put("meta",meta);return out;
 }
 private String amount(Object x){try{require(x!=null,"SOURCE_INCOMPLETE");return new BigDecimal(x.toString()).toPlainString();}catch(NumberFormatException e){throw new SourceException("SOURCE_INCOMPLETE",422,false);}}
 public synchronized Map<String,Object> international(Map<String,Object>request){String day=day(request.get("dataDay")).toString();
  try{db.update("INSERT INTO profit_international_day(data_day,attempts,state) VALUES(?,0,'READY')",day);}catch(org.springframework.dao.DuplicateKeyException ignored){}
  List<Map<String,Object>>old=db.queryForList("SELECT * FROM profit_international_day WHERE data_day=?",day);Map<String,Object>r=old.get(0);if("SUCCESS".equals(r.get("state")))return decode((String)r.get("payload"));
  int changed=db.update("UPDATE profit_international_day SET attempts=attempts+1,state='FETCHING' WHERE data_day=? AND state IN ('READY','RETRYABLE') AND attempts<3",day);if(changed!=1)throw new SourceException("SOURCE_UNAVAILABLE",503,false);
  int attempt=db.queryForObject("SELECT attempts FROM profit_international_day WHERE data_day=?",Integer.class,day);db.update("INSERT INTO profit_source_attempt(data_day,attempt_no,state) VALUES(?,?,'STARTED')",day,attempt);
  try{Map<String,Object>raw=gateway.internationalDay(day);db.update("UPDATE profit_source_attempt SET raw_response=? WHERE data_day=? AND attempt_no=?",encode(raw),day,attempt);Object receipt=unwrap(raw);require(receipt instanceof Map,"SOURCE_INCOMPLETE");Map<String,Object>doc=ConfiguredSourceGateway.map(receipt);require(Boolean.FALSE.equals(doc.get("truncated"))&&"Pigeon".equals(doc.get("source_platform")),"SOURCE_INCOMPLETE");require(boundary(doc.get("start_time"),day,"00:00:00")&&boundary(doc.get("end_time"),day,"23:59:59"),"SOURCE_INCOMPLETE");require(new HashSet<>(Arrays.asList("enterprise_id","account_id","send_channel_id")).equals(new HashSet<>((List<?>)doc.getOrDefault("group_by",Collections.emptyList()))),"SOURCE_INCOMPLETE");require(doc.get("rows") instanceof List&&doc.get("row_count") instanceof Number&&((List<?>)doc.get("rows")).size()==((Number)doc.get("row_count")).intValue(),"SOURCE_INCOMPLETE");for(Object item:(List<?>)doc.get("rows")){Map<String,Object>row=ConfiguredSourceGateway.map(item);amount(row.get("customer_total_amount"));amount(row.get("channel_total_amount"));boolean nonzero=new BigDecimal(row.get("customer_total_amount").toString()).signum()!=0||new BigDecimal(row.get("channel_total_amount").toString()).signum()!=0;if(nonzero)for(String key:Arrays.asList("enterprise_id","enterprise_name","account_id"))require(row.get(key)!=null&&!row.get(key).toString().trim().isEmpty(),"SOURCE_INCOMPLETE");if(new BigDecimal(row.get("channel_total_amount").toString()).signum()!=0)require(row.get("send_channel_id")!=null&&!row.get("send_channel_id").toString().trim().isEmpty(),"SOURCE_INCOMPLETE");}
   Map<String,Object>result=new HashMap<>();result.put("receipt",doc);result.put("meta",new HashMap<String,Object>(){{put("transport","LITELLM_REMOTE_MCP");put("adapterVersion","v1");put("sourceVersion",null);put("tool","yuexin_mcp_gateway-billing_mcp__query_daily_stats_summary");}});db.update("UPDATE profit_international_day SET state='SUCCESS',payload=?,raw_response=? WHERE data_day=?",encode(result),encode(raw),day);db.update("UPDATE profit_source_attempt SET state='SUCCESS' WHERE data_day=? AND attempt_no=?",day,attempt);return result;
  }catch(Exception e){boolean retry=e instanceof SourceException&&((SourceException)e).retryable;db.update("UPDATE profit_source_attempt SET state=? WHERE data_day=? AND attempt_no=?",retry?"TRANSPORT_FAILED":"SOURCE_REJECTED",day,attempt);db.update("UPDATE profit_international_day SET state=? WHERE data_day=?",retry?"RETRYABLE":"FAILED",day);if(e instanceof SourceException)throw (SourceException)e;throw new SourceException("SOURCE_INCOMPLETE",422,false);}
 }
 private boolean boundary(Object stamp,String day,String time){try{String s=String.valueOf(stamp);LocalDateTime local;try{local=OffsetDateTime.parse(s).atZoneSameInstant(ZoneId.of("Asia/Shanghai")).toLocalDateTime();}catch(java.time.format.DateTimeParseException e){local=LocalDateTime.parse(s);}return local.equals(LocalDateTime.parse(day+"T"+time));}catch(Exception e){return false;}}
 private Object unwrap(Object o){if(o instanceof String){try{return unwrap(json.readValue((String)o,Object.class));}catch(Exception e){return null;}}if(o instanceof Map){Map<String,Object>m=ConfiguredSourceGateway.map(o);require(!Boolean.TRUE.equals(m.get("isError"))&&!m.containsKey("error"),"SOURCE_INCOMPLETE");if(m.get("rows") instanceof List&&m.containsKey("truncated"))return m;for(String k:Arrays.asList("result","structuredContent","content","data","text")){Object v=unwrap(m.get(k));if(v!=null)return v;}}if(o instanceof List)for(Object v:(List<?>)o){Object d=unwrap(v);if(d!=null)return d;}return null;}
}
